import inspect
import logging
from taf.internal.managedobject import ManagedObject

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ManagedOamConnection(ManagedObject):
    """
    ManagedObject interface for OAM Connection, blueprint based on ManagedVcuOamConnection.
    """

    def __init__(self, oam_connection_cls, oam_connection_params, **kwargs):
        super(ManagedOamConnection, self).__init__(**kwargs)
        self._oam_connection_cls = oam_connection_cls
        self._oam_connection_params = oam_connection_params.copy()
        self._oam_connection_params.pop("reuse", None)
        if "port" not in self._oam_connection_params:
            self._oam_connection_params["port"] = 443
        if "secure" not in self._oam_connection_params:
            self._oam_connection_params["secure"] = True
        self._oam_connection = None

    @property
    def oam_connection_cls(self):
        """Returns the OAM connection class."""
        return self._oam_connection_cls

    _param_checks = {
        "host": lambda name: "host" in name and "remote" not in name,
        "port": lambda name: "port" in name,
        "user": lambda name: "user" in name and "remote" not in name and "node" not in name,
        "password": lambda name: "password" in name and "remote" not in name and "expir" not in name,
        "secure": lambda name: "secure" in name or "ssl" in name,
        "release": lambda name: "version" in name or "release" in name,
    }

    def _map_params(self):  # noqa: C901
        signature = inspect.signature(self._oam_connection_cls.__init__)
        mapped_params = {}
        params = self._oam_connection_params

        for own_name, value in params.items():
            is_foreign_name = self._param_checks.get(own_name, lambda name: False)
            name = next(
                (param_name for param_name in signature.parameters if is_foreign_name(param_name)),
                own_name)
            mapped_params[name] = value

        return mapped_params

    def _setup(self):
        logger.debug(f"connecting: {self._oam_connection_params}")
        mapped_params = self._map_params()
        self._oam_connection = self._oam_connection_cls(**mapped_params)

    def _teardown(self):
        logger.debug(f"disconnecting: {self._oam_connection_params}")
        try:
            self._oam_connection.disconnect()
        except Exception as exception:
            logger.debug(f"disconnecting failed due to {exception!r}")

    def __getattr__(self, name):
        attr = getattr(self._oam_connection, name)
        if callable(attr):
            return self._decorator(attr)
        return attr

    def _decorator(self, func):
        def wrapped(*args, **kwargs):
            try:
                logger.debug(f"Calling {func.__name__} with arguments {args} and keyword arguments {kwargs}")
                result = func(*args, **kwargs)
                logger.debug(f"{func.__name__} returned {result!r}")
                return result
            except Exception as e:
                logger.debug(f"{func.__name__} failed due to {e!r}")
                raise

        return wrapped

    @property
    def oam_connection(self):
        """Returns the underlying OAM connection object."""
        return self._oam_connection
